//! Tauri command wrappers around `fs_ops`'s framework-agnostic functions
//! (SPEC-0300-0011, SPEC-0200-0001 §2), following the same pattern as
//! `fs::commands` (fs_list_dir): the logic modules (`transfer`, `delete`,
//! `rename`, `create`, `preflight`) stay free of `Serialize`/Tauri types;
//! this module is the thin IPC boundary registered by the `app/` bootstrap
//! (`crate::run`, `lib.rs`) via `tauri::generate_handler!`.
//!
//! **R-40~R-45 (progress/cancel, ISS-0052):** `fs_ops_copy`/`fs_ops_move`
//! below take a caller-minted `operation_id` (a UUID string generated by
//! the frontend ipc wrapper, `shared/ipc/file-ops.ts`, via
//! `crypto.randomUUID()` — no backend UUID dependency is needed since the
//! id always originates from the caller) and emit one `ProgressEventDto`
//! per item boundary (`transfer::ProgressEvent`, see that module's doc
//! comment) through Tauri's event system. `fs_ops_cancel` looks up the
//! `operation_id` in `CancelRegistry` (Tauri `State`) and raises its
//! cancellation flag; `transfer::run_transfer_batch_with_progress` polls
//! that flag at each item boundary (R-43).
//!
//! **architecture-mapper follow-up note:** SPEC-0300-0011 §6 does not
//! specify a Tauri event name or a per-operation-id channel shape for
//! R-40~R-45 (it only specifies the event's *content*: start/fail/done +
//! name/index/total/code). `fs_ops://progress` as a single global event
//! broadcast via `AppHandle::emit`, filtered client-side by `operation_id`,
//! is a code-generator convention pending confirmation — flagging this so
//! it can be reconciled with the spec/architecture docs in a follow-up
//! pass rather than silently treated as settled.
//!
//! `fs_ops_copy`/`fs_ops_move` remain plain (non-`async fn`) `#[tauri::command]`
//! functions: Tauri already dispatches synchronous commands like these onto
//! its own worker thread pool rather than the main event loop, so the
//! blocking filesystem work they do does not stall the UI — this is the
//! sense in which they are "async-friendly" without needing `async fn` or
//! an app-level async runtime.

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};

use serde::Serialize;
use tauri::{AppHandle, Emitter, State};

use super::create;
use super::delete;
use super::preflight::MutatePreflightError;
use super::rename;
use super::transfer::{self, ConflictResolution, OpSummary, ProgressEvent};

/// R-42/R-43 (ISS-0052): per-operation-id cancellation-flag registry, keyed
/// by the caller-supplied `operation_id` so that multiple concurrent
/// copy/move batches (each with its own progress dialog) can be canceled
/// independently. Managed as ordinary Tauri `State` (`app/`'s `.manage()`
/// call in `lib.rs`).
///
/// This is a plain lookup table, *not* a Storage Provider abstraction
/// (SPEC-0400-0001 §4.1): no trait, no `dyn`, no generic backend parameter
/// — it only ever stores `Arc<AtomicBool>` cancellation flags.
#[derive(Default)]
pub struct CancelRegistry(Mutex<HashMap<String, Arc<AtomicBool>>>);

impl CancelRegistry {
    /// Registers a fresh, unset cancellation flag for `operation_id`,
    /// replacing any prior (necessarily already-finished) entry with the
    /// same id.
    fn register(&self, operation_id: &str) -> Arc<AtomicBool> {
        let flag = Arc::new(AtomicBool::new(false));
        self.0
            .lock()
            .expect("cancel registry mutex poisoned")
            .insert(operation_id.to_string(), flag.clone());
        flag
    }

    /// Removes `operation_id`'s entry once its batch has finished (whether
    /// it completed normally or was canceled), so `fs_ops_cancel` calls
    /// against a stale id are harmless no-ops rather than leaking flags.
    fn unregister(&self, operation_id: &str) {
        self.0.lock().expect("cancel registry mutex poisoned").remove(operation_id);
    }

    /// R-43: raises the cancellation flag for `operation_id`, if it is
    /// currently registered. A no-op for an unknown/already-finished id.
    fn request_cancel(&self, operation_id: &str) {
        if let Some(flag) = self.0.lock().expect("cancel registry mutex poisoned").get(operation_id) {
            flag.store(true, Ordering::Relaxed);
        }
    }
}

/// Serializable counterpart of `transfer::Failure` for the IPC boundary.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FailureDto {
    pub path: String,
    pub code: String,
    pub message: String,
}

/// Serializable counterpart of `transfer::OpSummary` for the IPC boundary.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct OpSummaryDto {
    pub ok: u32,
    pub failed: u32,
    pub total: u32,
    pub skipped: u32,
    pub failures: Vec<FailureDto>,
}

impl From<OpSummary> for OpSummaryDto {
    fn from(summary: OpSummary) -> Self {
        OpSummaryDto {
            ok: summary.ok,
            failed: summary.failed,
            total: summary.total,
            skipped: summary.skipped,
            failures: summary
                .failures
                .into_iter()
                .map(|f| FailureDto {
                    path: f.path.to_string_lossy().into_owned(),
                    code: f.code,
                    message: f.message,
                })
                .collect(),
        }
    }
}

// R-30/R-31: the UI passes "overwrite"/"skip" once the user has decided;
// anything else (including no explicit resolution) is the non-UI-path
// default, R-30-1/R-30-2 — reject conflicts rather than silently resolve.
fn resolution_from_str(value: &str) -> ConflictResolution {
    match value {
        "overwrite" => ConflictResolution::Overwrite,
        "skip" => ConflictResolution::Skip,
        _ => ConflictResolution::Reject,
    }
}

fn mutate_error_code(err: MutatePreflightError) -> String {
    match err {
        MutatePreflightError::Required => "invalid_name".to_string(),
        MutatePreflightError::InvalidName => "invalid_name".to_string(),
        MutatePreflightError::AlreadyExists => "already_exists".to_string(),
        MutatePreflightError::ParentNotFound => "parent_not_found".to_string(),
        MutatePreflightError::InvalidKind => "invalid_kind".to_string(),
    }
}

fn to_path_bufs(items: Vec<String>) -> Vec<PathBuf> {
    items.into_iter().map(PathBuf::from).collect()
}

/// R-40~R-45 (ISS-0052): the Tauri event name `fs_ops_copy`/`fs_ops_move`
/// broadcast per-item progress notifications under (see this module's doc
/// comment for the architecture-mapper follow-up note on this convention).
pub const PROGRESS_EVENT_NAME: &str = "fs_ops://progress";

/// Serializable counterpart of `transfer::ProgressEvent` for the IPC
/// boundary, matching the frozen frontend `ProgressEvent` shape
/// (`app/src/lib/features/file-ops/progress-modal.ts`) plus the
/// `operation_id` needed to tell concurrent batches apart on the wire.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ProgressEventDto {
    pub operation_id: String,
    #[serde(rename = "type")]
    pub event_type: String,
    pub name: String,
    pub index: u32,
    pub total: u32,
    pub code: Option<String>,
}

impl ProgressEventDto {
    fn from_event(operation_id: &str, event: ProgressEvent) -> Self {
        ProgressEventDto {
            operation_id: operation_id.to_string(),
            event_type: event.kind.as_str().to_string(),
            name: event.name,
            index: event.index,
            total: event.total,
            code: event.code,
        }
    }
}

/// R-21/R-40~R-44: batch copy (`items` into `destination`), broadcasting
/// one `fs_ops://progress` event per item boundary and honoring a
/// cancellation request raised against `operation_id` via `fs_ops_cancel`
/// (R-42/R-43). `operation_id` is minted by the caller (the frontend ipc
/// wrapper, via `crypto.randomUUID()`) before invoking this command.
#[tauri::command]
pub fn fs_ops_copy(
    app: AppHandle,
    cancel_registry: State<CancelRegistry>,
    operation_id: String,
    items: Vec<String>,
    destination: String,
    resolution: String,
) -> OpSummaryDto {
    let cancel_flag = cancel_registry.register(&operation_id);
    let event_operation_id = operation_id.clone();
    let summary = transfer::copy_batch_with_progress(
        &to_path_bufs(items),
        &PathBuf::from(destination),
        resolution_from_str(&resolution),
        move || cancel_flag.load(Ordering::Relaxed),
        move |event| {
            // R-40: best-effort broadcast — a failed emit (e.g. no window
            // yet listening) must not abort the batch itself.
            let _ = app.emit(PROGRESS_EVENT_NAME, ProgressEventDto::from_event(&event_operation_id, event));
        },
    );
    cancel_registry.unregister(&operation_id);
    summary.into()
}

/// R-21/R-23/R-40~R-44: batch move (`items` into `destination`). See
/// `fs_ops_copy`'s doc comment for the progress/cancellation contract.
#[tauri::command]
pub fn fs_ops_move(
    app: AppHandle,
    cancel_registry: State<CancelRegistry>,
    operation_id: String,
    items: Vec<String>,
    destination: String,
    resolution: String,
) -> OpSummaryDto {
    let cancel_flag = cancel_registry.register(&operation_id);
    let event_operation_id = operation_id.clone();
    let summary = transfer::move_batch_with_progress(
        &to_path_bufs(items),
        &PathBuf::from(destination),
        resolution_from_str(&resolution),
        move || cancel_flag.load(Ordering::Relaxed),
        move |event| {
            let _ = app.emit(PROGRESS_EVENT_NAME, ProgressEventDto::from_event(&event_operation_id, event));
        },
    );
    cancel_registry.unregister(&operation_id);
    summary.into()
}

/// R-42/R-43: request cancellation of a previously-started copy/move batch
/// identified by `operation_id` (the same id passed into `fs_ops_copy`/
/// `fs_ops_move`). A no-op if the operation has already finished or the id
/// is unknown — the frontend cancel button/Escape handler (R-42-2,
/// `features/file-ops/progress-modal.ts`) does not need to guard against
/// double-cancel or late cancellation itself.
#[tauri::command]
pub fn fs_ops_cancel(cancel_registry: State<CancelRegistry>, operation_id: String) {
    cancel_registry.request_cancel(&operation_id);
}

/// R-50/R-51: batch delete to the OS-standard trash bin.
#[tauri::command]
pub fn fs_ops_delete_trash(paths: Vec<String>) -> OpSummaryDto {
    delete::delete_to_trash(&to_path_bufs(paths)).into()
}

/// R-56/R-56-3: batch permanent delete.
#[tauri::command]
pub fn fs_ops_delete_permanently(paths: Vec<String>) -> OpSummaryDto {
    delete::delete_permanently(&to_path_bufs(paths)).into()
}

/// R-64: rename a single entry.
#[tauri::command]
pub fn fs_ops_rename(path: String, new_name: String) -> Result<(), String> {
    rename::rename_entry(&PathBuf::from(path), &new_name).map_err(mutate_error_code)
}

/// R-78: create a single new entry.
#[tauri::command]
pub fn fs_ops_create(parent: String, name: String, kind: String) -> Result<(), String> {
    create::create_entry(&PathBuf::from(parent), &name, &kind).map_err(mutate_error_code)
}
